let db,words=[],history=[],gardenCredits=[],gardenGame=null,gardenBusy=false,gardenLimit=12,journeyEntries=[],roundRecords=[],journeyBusy=false,view='learn',direction='ko-en',category='',queue=[],current=null,answered=false,session=0,search='',learningMode='spaced',round=null,currentResult=null,saving=false,currentDirection=null,answerMode='flash',revealed=false,faceShown=false,statsDay='',statsLimit=30,swipeBusy=false,undoSnapshot=null;
