const main=$('#main');if(main.addEventListener)bindLearningTaps(main);const bottomNav=document.querySelector('nav');const sizeNav=()=>document.documentElement.style.setProperty('--nav-height',bottomNav.getBoundingClientRect().height+'px');sizeNav();if('ResizeObserver'in window)new ResizeObserver(sizeNav).observe(bottomNav);
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',4500);}
function transaction(stores,action){return new Promise((resolve,reject)=>{const tx=db.transaction(stores,'readwrite');action(tx);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.farmError||tx.error||Error('Speichern abgebrochen.'));});}
function read(store){return new Promise((resolve,reject)=>{let r=db.transaction(store).objectStore(store).getAll();r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
async function refresh(){await transaction(['rewards','words'],initializeRewardsTransaction);rewardState=(await read('rewards')).find(r=>r.id==='main');await transaction(['journey','words','history'],initializeJourneyTransaction);[words,history,gardenCredits]=await Promise.all([read('words'),read('history'),read('garden')]);gardenGame=(await read('gardenGame')).find(g=>g.id==='main')||null;[journeyEntries,roundRecords]=await Promise.all([read('journey'),read('rounds')]);}
const cats=()=>[...new Set(words.map(w=>w.category))].sort((a,b)=>a.localeCompare(b,'de'));
function options(all=true){return(all?'<option value="">Alle Kategorien</option>':'')+'<option value="'+HARD_CATEGORY+'" '+(category===HARD_CATEGORY?'selected':'')+'>'+esc(hardCopy().icon+' '+hardCopy().name)+' ('+words.filter(w=>w.hard===true).length+')</option>'+cats().map(c=>`<option value="${esc(c)}" ${c===category?'selected':''}>${esc(c)}</option>`).join('');}
function due(w,dir=direction){if(!translationAnswers(w))return false;if(dir==='mixed')return dueDirections(w).length>0;return !w.srs[dir]||w.srs[dir].due<=Date.now();}
function dueTime(w){return direction==='mixed'?Math.min(...dueDirections(w).map(dir=>w.srs[dir]?.due||0)):(w.srs[direction]?.due||0);}
function filtered(){return words.filter(w=>inCategory(w,category));}
function render(){clearConfetti();main.classList.remove('learning','flash-learning','game-garden');document.querySelectorAll('nav button').forEach(b=>{b.classList.toggle('active',(b.dataset.view===view||((view==='journey'||view==='rewards')&&b.dataset.view==='garden')));b.setAttribute('aria-current',(b.dataset.view===view||((view==='journey'||view==='rewards')&&b.dataset.view==='garden'))?'page':'false');});({learn:renderLearn,words:renderWords,stats:renderStats,garden:renderGarden,journey:renderJourney,rewards:renderRewards,backup:renderBackup}[view])();bindSeasonControls(main);}
function startRound(onlyIds=null){
undoSnapshot=null;
const allowed=onlyIds?new Set(onlyIds):null,pool=filtered().filter(w=>translationAnswers(w)&&(!allowed||allowed.has(w.id))&&(learningMode==='cram'||due(w)));
if(!pool.length){toast('Keine passenden Vokabeln für diese Runde.');return;}
queue=learningMode==='cram'?shuffle(pool.map(w=>w.id)):pool.sort((a,b)=>dueTime(a)-dueTime(b)).map(w=>w.id);
round={id:crypto.randomUUID(),startedAt:Date.now(),wordIds:[...queue],attempts:[],mode:learningMode,answerMode,category,direction,total:queue.length,correct:0,answered:0,results:[],missedIds:[],finished:false,aborted:false};session=0;currentResult=null;revealed=false;faceShown=false;next();
}
